from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

from pupremote_hub import PUPRemoteHub

# Set up.
pr = PUPRemoteHub('A')
near_offset = 0
angle = 0
detected = 0
speed = 0
turn = 0
right = Motor(Port.E, Direction.COUNTERCLOCKWISE)
left = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(left, right, 89, 114)


# The main program starts here.
pr.add_command('line', 'bhh')
while True:
    detected, near_offset, angle = pr.call('line') or [0] * 3
    speed = 40 - abs(angle) / 4
    turn = near_offset * -1 / 5 + angle * -2 / 5
    left.dc(speed + turn * 0.25)
    right.dc(speed - turn * 0.25)
